<?php

declare(strict_types=1);

namespace CodeClubLuxembourg\Sb3Toolkit\Builder\Blocks;

use CodeClubLuxembourg\Sb3Toolkit\Builder\Block;
use CodeClubLuxembourg\Sb3Toolkit\Builder\Field\StopOption;
use CodeClubLuxembourg\Sb3Toolkit\Builder\Input;

/**
 * Typed factories for Scratch "Control" blocks.
 *
 * Generated by bin/generate-blocks.php — do not edit by hand.
 */
final class Control
{
    public static function wait(int|float|Block|Input $duration): Block
