        return Block::make('control_wait')
            ->input('DURATION', $duration);
    }

    /**
     * @param list<Block> $body
     */
    public static function repeat(int|float|Block|Input $times, array $body): Block
    {
        return Block::make('control_repeat')
            ->input('TIMES', $times)
            ->input('SUBSTACK', Block::stack(...$body));
    }

    /**
     * @param list<Block> $body
     */
    public static function forever(array $body): Block
    {
        return Block::make('control_forever')
            ->input('SUBSTACK', Block::stack(...$body));
    }

    /**
     * @param list<Block> $body
     */
    public static function if(Block $condition, array $body): Block
    {
        return Block::make('control_if')
            ->input('CONDITION', $condition)
            ->input('SUBSTACK', Block::stack(...$body));
    }

    /**
     * @param list<Block> $body
     * @param list<Block> $else
     */
    public static function ifElse(Block $condition, array $body, array $else): Block
    {
        return Block::make('control_if_else')
            ->input('CONDITION', $condition)
            ->input('SUBSTACK', Block::stack(...$body))
            ->input('SUBSTACK2', Block::stack(...$else));
