        return Block::make('control_start_as_clone');
    }

    public static function createCloneOf(string|Block $cloneOption): Block
    {
        return Block::make('control_create_clone_of')
            ->input('CLONE_OPTION', Input::menu('control_create_clone_of_menu', 'CLONE_OPTION', $cloneOption));
    }

